process BASICPY {
    tag "$meta.id"
    label 'process_single'

    container "docker.io/labsyspharm/basicpy-docker-mcmicro:1.2.0-patch5"

    input:
    tuple val(meta), path(image)

    output:
    tuple val(meta), path("*-dfp.ome.tif"), path("*-ffp.ome.tif"), emit: profiles
    tuple val("${task.process}"), val('basicpy'), val("1.2.0"), emit: versions_basicpy, topic: versions
    // WARN: Version information not provided by tool on CLI. Please update this string when bumping
    when:
    task.ext.when == null || task.ext.when

    script:
    // Exit if running this module with -profile conda / -profile mamba
    if (workflow.profile.tokenize(',').intersect(['conda', 'mamba']).size() >= 1) {
        error "Basicpy module does not support Conda. Please use Docker / Singularity instead."
    }
    def args    = task.ext.args   ?: ''
    def prefix  = task.ext.prefix ?: "${meta.id}"
    """
    /opt/main.py -i $image -o . --output-flatfield $prefix --output-darkfield $prefix $args
    """

    stub:
    // Exit if running this module with -profile conda / -profile mamba
    if (workflow.profile.tokenize(',').intersect(['conda', 'mamba']).size() >= 1) {
        error "Basicpy module does not support Conda. Please use Docker / Singularity instead."
    }
    def prefix  = task.ext.prefix ?: "${meta.id}"
    """
    touch ${prefix}-dfp.ome.tif
    touch ${prefix}-ffp.ome.tif
    """
}

nextflow_process {

    name "Test Process BASICPY"
    script "../main.nf"
    process "BASICPY"

    tag "modules"
    tag "modules_nfcore"
    tag "basicpy"

    test("basicpy - OME-TIFF") {

        when {
            process {
                """
                input[0] = [
                                [ id:'test' ],
                                file(params.modules_testdata_base_path + 'imaging/ome-tiff/cycif-tonsil-cycle1.ome.tif', checkIfExists: true),
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    process.out.findAll { key, val -> key.startsWith('versions') },
                    file(process.out.profiles.get(0).get(1)).name,
                    file(process.out.profiles.get(0).get(2)).name,
                    file(process.out.profiles.get(0).get(1)).size(),
                    Math.round(file(process.out.profiles.get(0).get(2)).size() / 1000) * 1000
                    ).match()
                },
            )
        }

    }

    test("basicpy - OME-TIFF - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                                [ id:'test' ],
                                file(params.modules_testdata_base_path + 'imaging/ome-tiff/cycif-tonsil-cycle1.ome.tif', checkIfExists: true),
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

}
